ndler(DescType fromType, DescType toType,									 AECoerceDescUPP handler, long handlerRefcon = NULL,									 bool isSysHandler = false){	enum { kFromTypeIsPtr = false, kFromTypeIsDesc = true };	InstallCoercionHandler(fromType, toType, (AECoercionHandlerUPP)handler,						   handlerRefcon, kFromTypeIsDesc, isSysHandler);}inline void InstallCoercePtrHandler(DescType fromType, DescType toType,									AECoercePtrUPP handler, long handlerRefcon = NULL,									bool isSysHandler = false){	enum { kFromTypeIsPtr = false, kFromTypeIsDesc = true };	InstallCoercionHandler(fromType, toType, (AECoercionHandlerUPP)handler,						   handlerRefcon, kFromTypeIsPtr, isSysHandler);}//----------------------------------------------------------------------------------------// Coercion Handlers//----------------------------------------------------------------------------------------Fixed GetFixed(const CAEDesc& thePropertyValue);void PutFixed(CAEDesc& thePropertyValue, Fixed value);void PutProperty(CAEDesc& thePropertyValue, DescType propertyType, const void* value,				 long propertySize);CTempDesc TempFSSpecDesc(const CFSSpec_AC& fileSpec);CTempDesc TempRectDesc(const CRect_AC& theRect);CTempDesc TempTypeDesc(DescType theType);CTempDesc TempStringDesc(const CString_AC& theString);CTempDesc TempBooleanDesc(bool theBoolean);CTempDesc TempEnumDesc(DescType theEnum);CTempDesc TempLongDesc(long theLong);CTempDesc TempDateTimeDesc(unsigned long theDateTime);CTempDesc TempRGBColorDesc(const CRGBColor_AC& theColor);CTempDesc TempObjectDesc(MScriptableObject* theObject);//CTempDesc TempPointDesc(Point value);//CTempDesc TempShortDesc(short value);CTempDesc TempFixedDesc(Fixed value);CTempDesc TempPropertyDesc(DescType propertyType, const void* value, long propertySize);#endif // __UAEUtils__